/// **The single predicate OD-P2-07 requires: does `class` confer ANY exemption from ANY governed control?** The
/// project-overlay widening refusal ([`crate::policy_precedence::overlap_is_no_less_restrictive`]) calls this to
/// decide whether a candidate pattern's class must be no less exempting than the kernel rule it overlaps — it does
/// not enumerate individual exemptions, so a class newly added to [`CLASS_EXEMPTIONS`] for a brand-new control is
/// automatically protected there without that function changing at all.
pub fn confers_any_exemption(class: &str) -> bool {
    !class_exemptions(class).is_empty()
}

#[derive(Debug, Clone)]
pub struct PathDecision {
    pub path: String,
    pub rule_pattern: Option<String>,
    pub attrs: Map<String, Value>,
}

impl PathDecision {
    pub fn class(&self) -> String {
        self.attrs
            .get("class")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown")
            .to_string()
    }
    pub fn is_secret(&self) -> bool {
        self.class() == SECRET_CLASS
            || self.attrs.get("sensitivity").and_then(|v| v.as_str()) == Some("secret")
    }
    /// Never read/indexed: secret-class or a sensitivity class in SECURITY_POLICY.never_index_classes.
    pub fn is_never_index(&self) -> bool {
        self.is_secret()
            || self
                .attrs
                .get("never_index")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
    }
    pub fn sensitivity(&self) -> String {
        self.str("sensitivity")
    }
    pub fn export_allowed(&self) -> bool {
        self.attrs.get("export").and_then(|v| v.as_str()) == Some("allowed")
    }
    pub fn flag(&self, key: &str) -> bool {
        if self.is_secret() && key.ends_with("_index") {
            return false;
        }
        self.attrs
            .get(key)
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
    }
    pub fn str(&self, key: &str) -> String {
        self.attrs
            .get(key)
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string()
    }
    pub fn namespace(&self) -> String {
        self.str("namespace")
    }
    pub fn default_retrieval(&self) -> bool {
        self.attrs
            .get("default_retrieval")
            .and_then(|v| v.as_bool())
            .unwrap_or(true)
            && !self.is_secret()
    }
}

